mapper.select:
                SELECT T0.FINPROD_ID AS FINPRODID,
		               T0.FINPROD_NAME AS FINPRODNAME,
		               T0.PROFIT_TYPE AS FINPRODTYPE,
		               t2.val_date AS VALDATE,
					   IFNULL(T2.BUILD_STATUS, '0') AS BUILDSTATUS,
		               T2.ERROR_TYPE AS ERRORTYPE
		          from FIN_PRODUCT T0
		          inner JOIN BOK_VALBAL_TABLE_LOG T2
		            ON T0.FINPROD_ID = T2.FINPROD_ID
		           AND T2.VAL_BAL_FLAG = #{fileType}
		         where 1 = 1
		           AND T0.FINPROD_TYPE = #{finprodType}

			  			AND T0.FINPROD_ID in 

			        	#{prdId} 



			  		AND T0.PROFIT_TYPE in 

			        	#{prodType} 



					 	and t2.val_date >= #{valDateBegin,jdbcType=DATE} 


						and t2.val_date <= #{valDateEnd,jdbcType=DATE} 


			  			AND IFNULL(T2.BUILD_STATUS, '0') in

			        		#{buildStatus} 


		           order by t2.VAL_DATE desc

SELECT FP.FINPROD_ID AS finProdId, FP.FINPROD_NAME AS finprodName, A.BOOKSET_ID booksetId, A.BAL_DATE balDate, A.O_CCY oCcy, B.VOUCH_NUM errorCount FROM ( SELECT @rownum := @rownum + 1 rownum, BT.BOOKSET_ID, BT.BAL_DATE, BT.O_CCY, IF ( ( @BOOKSET_ID = BT.BOOKSET_ID AND @BAL_DATE = BT.BAL_DATE AND @O_CCY = BT.O_CCY ), @rank := @rank + 1, @rank := 1 ) AS SEQ, @BOOKSET_ID := BT.BOOKSET_ID, @BAL_DATE := BT.BAL_DATE, @O_CCY := BT.O_CCY FROM ( SELECT * FROM BOK_BAL_TABLE_DATA ORDER BY BOOKSET_ID, BAL_DATE, O_CCY ) BT, ( SELECT @rownum := 0, @BOOKSET_ID := NULL, @BAL_DATE := NULL, @O_CCY := NULL, @rank := 0 ) a WHERE 1=1
AND BTD.BAL_DATE >= #{valDateBegin,jdbcType=DATE}
AND BTD.BAL_DATE <= #{valDateEnd,jdbcType=DATE}
) A LEFT JOIN BOK_VOUCH_MAIN_ERROR B ON A.BOOKSET_ID = B.BOOKSET_ID AND A.BAL_DATE = B.BOOK_DATE JOIN BOK_BOOKSET BB ON A.BOOKSET_ID = BB.BOOKSET_ID JOIN FIN_PRODUCT FP ON BB.ACCT_SUBJECT_ID = FP.FINPROD_ID where A.SEQ = '1'
AND FP.FINPROD_ID = #{prodId}
order by A.BOOKSET_ID, A.BAL_DATE, A.O_CCY

        SELECT COUNT(1) FROM BOK_VALBAL_TABLE_STATUS 
        WHERE 1=1

   			AND FINPROD_ID = #{prodId} 


         AND VAL_DATE>= STR_TO_DATE(#{valDateBegin},'%Y-%m-%d') 


         AND VAL_DATE<= STR_TO_DATE(#{valDateEnd},'%Y-%m-%d') 

		AND CHECK_STATUS = #{checkStatus} 
		AND VAL_BAL_FLAG = #{fileType}
